def f(g):
    H,W=len(g),len(g[0]); from collections import Counter
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; out=[[bg]*W for _ in range(H)]
